SELECT DATE(s1.candle_open_time) AS utc_day, COUNT(*) AS n, SUM(s5.generated_at > s1.generated_at) AS five_after_1m, SUM(s5.generated_at <= s1.generated_at) AS five_before_1m, AVG(TIMESTAMPDIFF(MICROSECOND, s1.generated_at, s5.generated_at)) / 1000 AS avg_ms_5m_minus_1m, MAX(TIMESTAMPDIFF(MICROSECOND, s1.generated_at, s5.generated_at)) / 1000 AS max_ms FROM crypto_ai.trade_signal s1 JOIN crypto_ai.trade_signal s5 ON s5.symbol = s1.symbol AND s5.interval_code = '5m' AND s5.candle_open_time = s1.candle_open_time - INTERVAL 4 MINUTE WHERE s1.interval_code = '1m' AND MOD(MINUTE(s1.candle_open_time), 5) = 4 AND s1.candle_open_time BETWEEN '2026-10-06 00:00:00' AND '2026-10-16 00:00:00' GROUP BY utc_day ORDER BY utc_day LIMIT 20